insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (8319, 30, 'Anonyme, digitale und mobile Suchtberatung ausbauen (Land)', 'Anonymität und kurze Wege senken die Hemmschwelle durch Scham; Wirkung auf die Inanspruchnahme ist kaum untersucht. Finanzierbar und kurzfristig umsetzbar.', 'offen', null, 'land', null, true, 'blind'),
  (8320, 30, 'Suchtberatung und Suchthilfe ausbauen (Land)', 'Behandlung wirkt gut belegt, erreicht aber zu wenige Menschen; mehr Angebot beseitigt Scham als Hürde nur indirekt. Landesmittel und Träger vorhanden.', 'belegt', 'https://europepmc.org/articles/PMC7068135', 'land', null, true, 'blind'),
  (8321, 30, 'Suchtberatung dauerhaft finanzieren und Struktur absichern (Land)', 'Sichert vorhandene Angebote, schafft aber kaum zusätzlichen Zugang und senkt die Scham-Hürde nicht. Rechtlich und finanziell leicht umsetzbar.', 'offen', null, 'land', null, true, 'blind'),
  (8322, 30, 'Konsumräume, Streetwork, Substitution und kürzere Wartezeiten ausbauen (Land)', 'Konsumräume erreichen Randgruppen und senken Überdosierungen ohne mehr Konsum; Substitution ist gut belegt. Räume brauchen Landesrecht, Therapieplätze Personal.', 'belegt', 'https://doi.org/10.1016/j.drugalcdep.2014.10.012', 'land', null, true, 'blind'),
  (8323, 30, 'Beratung und Versorgung für wohnungslose Menschen mit Suchtberatung ausbauen (Land)', 'Erreicht eine Gruppe, die Behandlung häufig meidet; Wirkung kaum untersucht. Landesmittel und Träger vorhanden.', 'offen', null, 'land', null, true, 'blind'),
  (8324, 30, 'Suchthilfe und Substitution im Strafvollzug absichern (Land)', 'Substitutionsbehandlung ist gut belegt, auch in Haft; senkt Rückfall und Todesfälle. Setzt an Behandlungszugang an, nicht an Scham allgemein. Länderzuständigkeit.', 'belegt', 'https://europepmc.org/articles/PMC7068135', 'land', null, true, 'blind'),
  (8325, 30, 'Prävention, Beratung und Therapie bei Sucht ausbauen (Bund)', 'Behandlung ist belegt wirksam, die Versorgung liegt aber vor allem bei Ländern, Kommunen und Kassen; der Bund kann Programme und Rahmen setzen.', 'belegt', 'https://europepmc.org/articles/PMC7068135', 'bund', null, true, 'blind'),
  (8326, 30, 'Prävention und Aufklärung zu Glücksspiel ausbauen oder finanzieren (Land)', 'Aufklärung wirkte in weniger als der Hälfte der Studien zu Jugendprogrammen; Angebot und Werbung bleiben unverändert. Mit Landesmitteln leicht umsetzbar.', 'gemischt', 'https://doi.org/10.1016/j.addbeh.2018.11.048', 'land', null, true, 'blind'),
  (8327, 30, 'Illegales Glücksspiel konsequent verfolgen (Land)', 'Verfolgung kann illegale Angebote eindämmen; Wirkung auf Spielschäden kaum untersucht, Online-Anbieter sind schwer zu fassen. Braucht Personal und Länderabstimmung.', 'offen', null, 'land', null, true, 'blind'),
  (8328, 30, 'Werbung für Tabak und Alkohol stärker beschränken (Bund)', 'Wer mehr Werbung wahrnimmt, raucht später häufiger; Beschränkungen verringern die Reichweite, aber nicht vollständig. Bundesrecht, EU-Spielraum vorhanden.', 'belegt', 'https://www.cochrane.org/evidence/CD003439_does-advertising-and-promotion-tobacco-products-make-children-more-likely-smoke', 'bund', null, true, 'blind'),
  (8329, 30, 'Legalen Cannabisverkauf über EU- und UN-Änderungen ermöglichen (Bund)', 'Geprüfte Qualität kann Verunreinigungen senken; Studien zeigen gemischte Folgen für Konsum und Gesundheit. Hängt von EU- und UN-Recht ab, das Deutschland nicht allein ändert.', 'gemischt', 'https://europepmc.org/articles/PMC10176789', 'bund', null, true, 'blind'),
  (8330, 30, 'Cannabis-Freigabe außerhalb medizinischer Nutzung zurücknehmen (Bund)', 'Kann den legalen Konsum senken, setzt aber nicht an unbekannten Wirkstoffen am Schwarzmarkt an; Studien zur Legalisierung sind gemischt. Per Bundesgesetz umsetzbar.', 'gemischt', 'https://europepmc.org/articles/PMC10176789', 'bund', null, true, 'blind')
