  (30, 14, 'MV', 'keine', 'Inhaltsverzeichnis (S. 2), Kapitel Gesundheit und Versorgungssicherheit (S. 40–42), Gewaltschutz (S. 52–53), Hochschul-Gesundheit (S. 115) und Fundstelle S. 44 gelesen; Volltextsuche nach Sucht, Alkohol, Glücksspiel, Sportwetten, Drogen, Cannabis, Tabak, Spielerschutz, Entzug, Selbsthilfe ergab keine einschlägige Stelle.', '2026-10-06', true, '{3001,3004,3006}'),
  (30, 14, 'ST', 'keine', 'Inhaltsverzeichnis (S. 2) sowie Kapitel Soziales (S. 35-39), Sicherheit (S. 47-49), Gesundheit und Rettungswesen (S. 59-63) und Ladenöffnung (S. 7) gelesen; keine Treffer und keine Fundstellen, nichts zu Alkohol, Glücksspiel, Suchtberatung oder Entstigmatisierung.', '2026-10-06', true, '{3001,3004,3006}'),
  (30, 15, null, 'massnahmen', null, '2026-10-06', true, '{3001,3002,3003,3004,3005,3006}'),
  (30, 15, 'BE', 'keine', 'Inhaltsverzeichnis (S. 3), Kapitel ‚Gesundheit‘ (S. 69–73), ‚Wirtschaft & Soziales‘ (S. 51–52) und ‚Kinder, Jugend & Familie‘ (S. 62–63) gelesen; nichts zu Alkohol-Verfügbarkeit, Glücksspielangeboten, Suchtberatung, Suchtbehandlung oder Entstigmatisierung.', '2026-10-06', true, '{3001,3004,3006}'),
