  (30, 16, 'MV', 'keine', 'Kapitel 6 (S. 10–11), 7 (S. 11–13), 10 (S. 18–19), 11 (S. 19–20), 15 (S. 24–25), 16 (S. 25–26), 19 (S. 28) und Fundstelle S. 14 gelesen; Stichwortsuche (Sucht, Alkohol, Glücksspiel, Cannabis, Drogen, Abhängigkeit, Stigma, Tabak) ohne einschlägigen Treffer. Nichts zu Alkoholverkauf, Glücksspielrecht oder Suchtberatung.', '2026-10-06', true, '{3001,3004,3006}'),
  (30, 16, 'ST', 'massnahmen', null, '2026-10-06', true, '{3001,3004,3006}'),
  (30, 17, null, 'keine', 'Kein Inhaltsverzeichnis; Kapitel Gesundheit und Pflege (S. 26-27), Verbraucher (S. 30-31), Familie und Bildung (S. 23-25, 31-32), Sicherheit/Polizei (S. 34-36), Corona-Aufarbeitung (S. 40-41) und Fundstellen S. 13 und 18 gelesen; Volltextsuche nach Sucht, Drogen, Alkohol, Tabak, Cannabis, Glücksspiel, Wetten, Konsum, Prävention: keine Zusage zu Alkohol, Tabak, Glücksspiel, Drogen oder Suchthilfe.', '2026-10-06', true, '{3001,3002,3003,3004,3005,3006}'),
  (30, 17, 'BE', 'massnahmen', null, '2026-10-06', true, '{3001,3004,3006}'),
  (30, 17, 'MV', 'massnahmen', null, '2026-10-06', true, '{3001,3004,3006}'),
  (30, 17, 'ST', 'keine', 'Inhaltsverzeichnis, Kapitel 4.4 Gesundheit (S. 55-61, v. a. Psychische Gesundheit ernst nehmen, S. 58-59), Schulsozialarbeit (S. 47-48) und Kapitel 5.2 Sicherheit (S. 65-66) gelesen; keine Zusage zu Alkohol, Glücksspiel oder Suchthilfe. Suchtprävention steht nur als Ziel und Bedarfsaussage.', '2026-10-06', true, '{3001,3004,3006}'),
  (30, 18, null, 'massnahmen', null, '2026-10-07', true, '{3001,3002,3003,3004,3005,3006}'),
