  (30, 18, 'MV', 'keine', 'Inhaltsverzeichnis (S. 2-3), Kapitel Gesellschaftlicher Zusammenhalt (S. 13-14), Gesundheit und Wohlbefinden (S. 29-34) gelesen; Textsuche nach Sucht, Alkohol, Glücksspiel, Wetten, Drogen, Cannabis, Tabak, Stigma ohne Treffer. Keine Zusage zu Suchtprävention, Glücksspielrecht oder Suchthilfe.', '2026-10-08', true, '{3001,3004,3006}'),
  (30, 18, 'ST', 'keine', 'Kapitel ''Gesundheit schützen - Suchtverhalten wirksam eindämmen'' (S. 146), Nichtraucherschutz (S. 46 gedruckt), Psychische Gesundheit/Männerberatung (ca. S. 125-128) und Fundstellen S. 15, 37, 128 gelesen; nichts zu Verkaufsstellen/Jugendschutz Alkohol, Glücksspiel oder Suchtberatung/Entstigmatisierung.', '2026-10-08', true, '{3001,3004,3006}');
