  (8331, 30, 11, null, 'Die Teillegalisierung von Cannabis wird rückgängig gemacht.', '{3005}', 8330, 1, 3, null, 'Kann den legalen Konsum senken, setzt aber nicht an unbekannten Wirkstoffen am Schwarzmarkt an; Studien zur Legalisierung sind gemischt. Per Bundesgesetz umsetzbar.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=39', 'https://europepmc.org/articles/PMC10176789', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8332, 30, 11, 'MV', 'Sucht- und Drogenberatung dauerhaft stärken; Perspektivplan sichert Finanzierung und Organisation der Beratungsstellen.', '{3006}', 8321, 1, 3, null, 'Sichert vorhandene Angebote, schafft aber kaum zusätzlichen Zugang und senkt die Scham-Hürde nicht. Rechtlich und finanziell leicht umsetzbar.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=80', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8333, 30, 11, 'MV', 'Polizei und Aufsichtsbehörden personell, technisch und rechtlich so ausstatten, dass illegales Glücksspiel online und vor Ort verfolgt wird.', '{3004}', 8327, 2, 2, null, 'Verfolgung kann illegale Angebote eindämmen; Wirkung auf Spielschäden kaum untersucht, Online-Anbieter sind schwer zu fassen. Braucht Personal und Länderabstimmung.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=81', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8334, 30, 11, 'MV', 'Mehr Mittel aus den Erträgen der staatlichen Toto-Lotto GmbH für Suchtprävention beim Glücksspiel bereitstellen.', '{3004}', 8326, 1, 3, null, 'Aufklärung wirkte in weniger als der Hälfte der Studien zu Jugendprogrammen; Angebot und Werbung bleiben unverändert. Mit Landesmitteln leicht umsetzbar.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=82', 'https://doi.org/10.1016/j.addbeh.2018.11.048', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8335, 30, 11, 'ST', 'Regeln für Glücksspiel so ausgestalten, dass Jugend- und Spielerschutz gestärkt und illegales Glücksspiel bekämpft wird.', '{3004}', null, 1, 2, null, 'Nennt Ziele für das Regelwerk ohne konkrete Mittel; Wirkung hängt von der Ausgestaltung ab. Änderungen brauchen alle Länder.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=9', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8336, 30, 12, null, 'Strengere Regulierung, Werbebeschränkungen und Altersgrenzen für Alkohol, Einweg-Zigaretten und neuartige Nikotinprodukte.', '{3003}', 8328, 2, 3, null, 'Wer mehr Werbung wahrnimmt, raucht später häufiger; Beschränkungen verringern die Reichweite, aber nicht vollständig. Bundesrecht, EU-Spielraum vorhanden.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=28', 'https://www.cochrane.org/evidence/CD003439_does-advertising-and-promotion-tobacco-products-make-children-more-likely-smoke', 'belegt', '2026-10-06', false, true, 'blind'),
  (8337, 30, 12, null, 'Schritte einleiten, um eine europarechtskonforme Legalisierung von Cannabis zu ermöglichen.', '{3005}', 8329, 2, 1, null, 'Geprüfte Qualität kann Verunreinigungen senken; Studien zeigen gemischte Folgen für Konsum und Gesundheit. Hängt von EU- und UN-Recht ab, das Deutschland nicht allein ändert.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=46', 'https://europepmc.org/articles/PMC10176789', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8338, 30, 12, 'BE', 'Beratungs- und Versorgungsangebote für wohnungslose Menschen, darunter Suchtberatung, ausbauen und dauerhaft sichern.', '{3006}', 8323, 2, 3, null, 'Erreicht eine Gruppe, die Behandlung häufig meidet; Wirkung kaum untersucht. Landesmittel und Träger vorhanden.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=51', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8339, 30, 12, 'BE', 'Therapieangebote für suchtkranke Menschen ausbauen.', '{3006}', null, 2, 3, null, 'Mehr Therapie erweitert den Zugang, Drugchecking macht Inhalte erkennbar; beides in Deutschland erst in Teilen untersucht. Landesmittel und rechtliche Grundlage vorhanden.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=51', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8340, 30, 12, 'BE', 'Abschaffung des begleiteten Trinkens für Jugendliche unter 16 Jahren unterstützen.', '{3001}', null, 1, 2, null, 'Schließt einen legalen Zugang für unter 16-Jährige, betrifft aber nur eine kleine Gruppe. Regelung liegt im Bundesrecht, das Land kann nur im Bundesrat unterstützen.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=51', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8341, 30, 12, 'MV', 'Auf Bundesebene ein Suchtpräventionsprogramm für Kommunen anstoßen, das Prävention vor Ort bei Alkohol, Nikotin, Cannabis und Drogen finanziert.', '{3001}', null, 1, 2, null, 'Kommunale Prävention zeigt in Studien gemischte Wirkung auf Konsum. Hängt von einem Bundesprogramm ab, das das Land nur anstoßen kann.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=31', 'https://www.cochrane.org/evidence/CD003020_do-school-based-programmes-prevent-illicit-drug-use', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8342, 30, 12, 'MV', 'Landesfachstelle für Kinder aus psychisch und suchtbelasteten Familien über 2027 hinaus finanzieren, um Hilfe zu bieten und Sucht vorzubeugen.', '{3006}', 8321, 1, 3, null, 'Sichert vorhandene Angebote, schafft aber kaum zusätzlichen Zugang und senkt die Scham-Hürde nicht. Rechtlich und finanziell leicht umsetzbar.', 'https://spd-mv.de/uploads/bilderpool/2-Mecklenburg-Vorpommern/Wahlen-und-Kandidaturen/2026-Landtagswahlen/SPD_MV_Programm_2026.pdf#page=35', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8343, 30, 12, 'ST', 'Soziale Beratungsangebote einschließlich Suchtberatung landesweit stärken und besser vernetzen.', '{3006}', 8320, 2, 3, null, 'Behandlung wirkt gut belegt, erreicht aber zu wenige Menschen; mehr Angebot beseitigt Scham als Hürde nur indirekt. Landesmittel und Träger vorhanden.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=15', 'https://europepmc.org/articles/PMC7068135', 'belegt', '2026-10-06', false, true, 'blind'),
  (8344, 30, 13, null, 'Werbung für Tabak und Alkohol stärker regulieren.', '{3003}', 8328, 2, 3, null, 'Wer mehr Werbung wahrnimmt, raucht später häufiger; Beschränkungen verringern die Reichweite, aber nicht vollständig. Bundesrecht, EU-Spielraum vorhanden.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=94', 'https://www.cochrane.org/evidence/CD003439_does-advertising-and-promotion-tobacco-products-make-children-more-likely-smoke', 'belegt', '2026-10-06', false, true, 'blind'),
  (8345, 30, 13, null, 'Einheitliche, neutrale Verpackungen ohne Markenlogos für Tabakprodukte einführen.', '{3003}', null, 1, 3, null, 'Neutrale Packungen machen Tabak weniger attraktiv, der Rückgang des Konsums ist klein. EU-Recht erlaubt es, Bundesgesetz genügt.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=94', 'https://www.cochrane.org/evidence/CD011244_do-plain-tobacco-packaging-reduce-smoking', 'belegt', '2026-10-06', false, true, 'blind'),
  (8346, 30, 13, null, 'Cannabis in lizenzierten Fachgeschäften verkaufen, um Schwarzmarkt und organisierte Kriminalität einzudämmen.', '{3005}', 8329, 2, 1, null, 'Geprüfte Qualität kann Verunreinigungen senken; Studien zeigen gemischte Folgen für Konsum und Gesundheit. Hängt von EU- und UN-Recht ab, das Deutschland nicht allein ändert.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=96', 'https://europepmc.org/articles/PMC10176789', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8347, 30, 13, null, 'Drogenkriminalität auf organisierten Handel konzentrieren und dafür Kriminalpolizei und Zoll stärken.', '{3005}', null, 1, 2, null, 'Verfolgung des organisierten Handels macht den Markt nicht sicherer; Wirkung auf Verfügbarkeit und Reinheit ist kaum belegt. Personalaufbau bei Polizei und Zoll dauert.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=96', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8348, 30, 13, null, 'Angebote für Prävention, Therapie und Gesundheitsschutz auch bei legalen Suchtmitteln ausbauen.', '{3006}', 8325, 2, 2, null, 'Behandlung ist belegt wirksam, die Versorgung liegt aber vor allem bei Ländern, Kommunen und Kassen; der Bund kann Programme und Rahmen setzen.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=96', 'https://europepmc.org/articles/PMC7068135', 'belegt', '2026-10-06', false, true, 'blind'),
  (8349, 30, 13, 'BE', 'Werbung für Sportwetten und Glücksspiel einschränken, Warnhinweise in der Werbung vorschreiben, Werbung gemeinnütziger Vereine verbieten.', '{3004}', null, 2, 2, null, 'Weniger Werbung und Warnhinweise können Spielen mindern; Warnhinweise wirken in Studien gemischt. Änderungen am Glücksspielstaatsvertrag brauchen alle Länder.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=38', null, 'gemischt', '2026-10-06', false, true, 'blind'),
  (8350, 30, 13, 'BE', 'Spielersperrdatei „Oasis“ ausbauen, auch für glücksspielartige Elemente digital; im Online-Glücksspiel Vermögensprüfungen und feste Einzahlungslimits als Standard.', '{3004}', null, 2, 2, null, 'Sperren und Limits helfen vor allem bei Pflicht statt Freiwilligkeit; Reviews zeigen begrenzte Wirkung wegen Umgehung. Änderungen brauchen alle Länder.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=210', 'https://doi.org/10.1016/j.addbeh.2018.11.048', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8351, 30, 13, 'BE', 'Verhaltensbezogene Süchte wie Glücksspiel- oder Medienspielsucht systematisch in die Hilfestrukturen einbinden.', '{3006}', 8320, 2, 3, null, 'Behandlung wirkt gut belegt, erreicht aber zu wenige Menschen; mehr Angebot beseitigt Scham als Hürde nur indirekt. Landesmittel und Träger vorhanden.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=210', 'https://europepmc.org/articles/PMC7068135', 'belegt', '2026-10-06', false, true, 'blind'),
  (8352, 30, 13, 'BE', 'Wartezeiten auf Therapieplätze verkürzen und niedrigschwellige Hilfsangebote ausbauen, besonders für junge und sozial benachteiligte Menschen.', '{3006}', 8322, 2, 2, null, 'Konsumräume erreichen Randgruppen und senken Überdosierungen ohne mehr Konsum; Substitution ist gut belegt. Räume brauchen Landesrecht, Therapieplätze Personal.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=209', 'https://doi.org/10.1016/j.drugalcdep.2014.10.012', 'belegt', '2026-10-06', false, true, 'blind'),
  (8353, 30, 13, 'BE', 'Sucht- und Präventionsarbeit im Strafvollzug absichern, Zugang zu Substitution und Therapie sowie Anschlussversorgung nach der Haft.', '{3006}', 8324, 2, 3, null, 'Substitutionsbehandlung ist gut belegt, auch in Haft; senkt Rückfall und Todesfälle. Setzt an Behandlungszugang an, nicht an Scham allgemein. Länderzuständigkeit.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=210', 'https://europepmc.org/articles/PMC7068135', 'belegt', '2026-10-06', false, true, 'blind'),
