  (8355, 30, 13, 'ST', 'Kommunale Suchtberatungsstellen verlässlich fördern und Beratung zu Online-, Medien- und Gamingsucht stärken.', '{3006}', 8320, 2, 3, null, 'Behandlung wirkt gut belegt, erreicht aber zu wenige Menschen; mehr Angebot beseitigt Scham als Hürde nur indirekt. Landesmittel und Träger vorhanden.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=85', 'https://europepmc.org/articles/PMC7068135', 'belegt', '2026-10-06', false, true, 'blind'),
  (8356, 30, 13, 'ST', 'Anonyme, rund um die Uhr erreichbare digitale Suchtberatung dauerhaft aus Landesmitteln finanzieren.', '{3006}', 8319, 2, 3, null, 'Anonymität und kurze Wege senken die Hemmschwelle durch Scham; Wirkung auf die Inanspruchnahme ist kaum untersucht. Finanzierbar und kurzfristig umsetzbar.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=85', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8357, 30, 14, null, 'Cannabis-Legalisierung beibehalten, um den Schwarzmarkt einzudämmen sowie Qualität und Jugendschutz zu sichern.', '{3005}', null, 2, 3, null, 'Kontrollierte Qualität senkt Verunreinigungen bei Cannabis; Studien zeigen gemischte Folgen für Konsum und Gesundheit. Rechtsrahmen besteht bereits.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=34', 'https://europepmc.org/articles/PMC10176789', 'gemischt', '2026-10-06', false, true, 'blind'),
