  (8365, 30, 15, 'MV', 'Alkohol- und Drogenprävention im Land finanziell und strukturell absichern.', '{3001}', null, 1, 3, null, 'Prävention sichert vorhandene Arbeit, Programme zeigen gemischte Wirkung auf Konsum. Mit Landesmitteln leicht umsetzbar.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=63', 'https://www.cochrane.org/evidence/CD003020_do-school-based-programmes-prevent-illicit-drug-use', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8366, 30, 16, null, 'Werbe- und Sponsoringverbot für Tabak, Alkohol, andere Drogen und Glücksspielangebote, begleitet von Aufklärungskampagnen zu Alkohol-, Drogen- und Spielsucht.', '{3003}', null, 3, 2, null, 'Werbung erhöht die Konsumbereitschaft, ein Verbot entfernt die Ursache direkt. Glücksspielwerbung ist Ländersache, Alkohol-Verbot hat verfassungs- und EU-rechtliche Hürden.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', 'https://www.cochrane.org/evidence/CD003439_does-advertising-and-promotion-tobacco-products-make-children-more-likely-smoke', 'belegt', '2026-10-06', false, true, 'blind'),
  (8367, 30, 16, null, 'Drogenkonsum vollständig entkriminalisieren und stattdessen medizinische und sozialarbeiterische Interventionsprogramme schaffen.', '{3005}', null, 2, 2, null, 'Strafandrohung hängt mit schlechterem Zugang zu Prävention und Behandlung zusammen; Studien meist beobachtend. Braucht Gesetzesänderung und Aufbau der Hilfsprogramme.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', 'https://europepmc.org/articles/PMC6005363', 'belegt', '2026-10-06', false, true, 'blind'),
  (8368, 30, 16, null, 'Cannabis vollständig legalisieren und dafür die nötigen Änderungen auf EU- und UN-Ebene durchsetzen.', '{3005}', 8329, 2, 1, null, 'Geprüfte Qualität kann Verunreinigungen senken; Studien zeigen gemischte Folgen für Konsum und Gesundheit. Hängt von EU- und UN-Recht ab, das Deutschland nicht allein ändert.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', 'https://europepmc.org/articles/PMC10176789', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8369, 30, 16, null, 'Flächendeckend Drogenkonsumräume, sterile Konsumutensilien, Medikamente gegen Überdosierung und Drugchecking verfügbar machen.', '{3005}', null, 2, 2, null, 'Konsumräume senken Überdosierungen ohne mehr Konsum oder Kriminalität; Drugchecking ist weniger untersucht. Räume sind Ländersache, der Bund kann Rahmen und Mittel setzen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', 'https://doi.org/10.1016/j.drugalcdep.2014.10.012', 'belegt', '2026-10-06', false, true, 'blind'),
  (8370, 30, 16, null, 'Präventions-, Beratungs- und Hilfsangebote im Bereich Drogen und Sucht stärken.', '{3006}', 8325, 2, 2, null, 'Behandlung ist belegt wirksam, die Versorgung liegt aber vor allem bei Ländern, Kommunen und Kassen; der Bund kann Programme und Rahmen setzen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=20', 'https://europepmc.org/articles/PMC7068135', 'belegt', '2026-10-06', false, true, 'blind'),
  (8371, 30, 16, 'BE', 'Land soll sich auf Bundesebene für ein weitgehendes Werbeverbot für Sportwetten einsetzen.', '{3004}', null, 2, 1, null, 'Weniger Werbung hängt mit weniger Wetten zusammen; das Land kann nur auf Bundesebene werben, Zustimmung anderer Länder und des Bundes fehlt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=324', null, 'gemischt', '2026-10-06', false, true, 'blind'),
  (8372, 30, 16, 'BE', 'Präventions- und Aufklärungsmaßnahmen zu Sportwetten auf Landesebene deutlich verstärken, besonders für junge Männer in Sportvereinen.', '{3004}', 8326, 1, 3, null, 'Aufklärung wirkte in weniger als der Hälfte der Studien zu Jugendprogrammen; Angebot und Werbung bleiben unverändert. Mit Landesmitteln leicht umsetzbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=324', 'https://doi.org/10.1016/j.addbeh.2018.11.048', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8373, 30, 16, 'BE', 'Äußeres Erscheinungsbild von Wettbüros regeln, etwa getönte Außenfenster.', '{3004}', null, 1, 3, null, 'Weniger Sichtbarkeit kann Anreize senken, ändert aber Zugang und Einsatzhöhe nicht. Per Landesrecht rasch umsetzbar.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=324', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8374, 30, 16, 'BE', 'Angebote der Sucht- und Drogenhilfe verstetigen und ausbauen, ebenso bedarfsorientierte ambulante Therapieangebote.', '{3006}', 8320, 2, 3, null, 'Behandlung wirkt gut belegt, erreicht aber zu wenige Menschen; mehr Angebot beseitigt Scham als Hürde nur indirekt. Landesmittel und Träger vorhanden.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=145', 'https://europepmc.org/articles/PMC7068135', 'belegt', '2026-10-06', false, true, 'blind'),
  (8375, 30, 16, 'BE', 'Psychosoziale Betreuung für Abhängige weiterentwickeln und niedrigschwelligen Zugang zur Substitutionsbehandlung vorantreiben.', '{3006}', 8322, 2, 2, null, 'Konsumräume erreichen Randgruppen und senken Überdosierungen ohne mehr Konsum; Substitution ist gut belegt. Räume brauchen Landesrecht, Therapieplätze Personal.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=145', 'https://doi.org/10.1016/j.drugalcdep.2014.10.012', 'belegt', '2026-10-06', false, true, 'blind'),
  (8376, 30, 16, 'BE', 'Suchthilfe und psychiatrische Versorgung über das Gesundheitsdienstgesetz ausweiten, auch mit Diagnostik und Therapie zulasten der Krankenkassen.', '{3006}', null, 2, 2, null, 'Mehr Suchthilfe und Therapie erweitert den Zugang; Kassenleistungen hängen an Bundesrecht und Selbstverwaltung. Wirkung auf die Scham-Hürde ist indirekt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=130', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8377, 30, 16, 'BE', 'Zwei Versorgungszentren für obdach- und wohnungslose Menschen finanzieren, unter anderem mit Beratung bei Suchterkrankungen.', '{3006}', 8323, 2, 3, null, 'Erreicht eine Gruppe, die Behandlung häufig meidet; Wirkung kaum untersucht. Landesmittel und Träger vorhanden.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=130', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8378, 30, 16, 'ST', 'Mobile Beratungsstellen für Sucht-, Schulden- und Familienprobleme sowie Sozialarbeit und Familienhilfe im ländlichen Raum verfügbar machen.', '{3006}', 8319, 2, 3, null, 'Anonymität und kurze Wege senken die Hemmschwelle durch Scham; Wirkung auf die Inanspruchnahme ist kaum untersucht. Finanzierbar und kurzfristig umsetzbar.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=134', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8379, 30, 17, 'BE', 'Hilfsangebote für Drogenkranke wie medizinische Betreuung und Unterstützung bei Substitutionstherapien ausweiten.', '{3006}', 8322, 2, 2, null, 'Konsumräume erreichen Randgruppen und senken Überdosierungen ohne mehr Konsum; Substitution ist gut belegt. Räume brauchen Landesrecht, Therapieplätze Personal.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=12', 'https://doi.org/10.1016/j.drugalcdep.2014.10.012', 'belegt', '2026-10-06', false, true, 'blind'),
  (8380, 30, 17, 'MV', 'Mindestens ein Prozent der Glücksspielerlöse des Vorjahres verbindlich für Suchtprävention bei Glücksspiel einsetzen.', '{3004}', 8326, 1, 3, null, 'Aufklärung wirkte in weniger als der Hälfte der Studien zu Jugendprogrammen; Angebot und Werbung bleiben unverändert. Mit Landesmitteln leicht umsetzbar.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=64', 'https://doi.org/10.1016/j.addbeh.2018.11.048', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8381, 30, 17, 'MV', 'Schwerpunktberatungsstellen und Landesfachstelle Glücksspielsucht personell und sachlich deutlich stärker ausstatten.', '{3006}', 8320, 2, 3, null, 'Behandlung wirkt gut belegt, erreicht aber zu wenige Menschen; mehr Angebot beseitigt Scham als Hürde nur indirekt. Landesmittel und Träger vorhanden.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=64', 'https://europepmc.org/articles/PMC7068135', 'belegt', '2026-10-06', false, true, 'blind'),
  (8382, 30, 17, 'MV', 'Flächendeckende Präventionsangebote gegen Glücksspielsucht, auch mobil und digital, vor allem im ländlichen Raum.', '{3004}', 8326, 1, 3, null, 'Aufklärung wirkte in weniger als der Hälfte der Studien zu Jugendprogrammen; Angebot und Werbung bleiben unverändert. Mit Landesmitteln leicht umsetzbar.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=64', 'https://doi.org/10.1016/j.addbeh.2018.11.048', 'gemischt', '2026-10-06', false, true, 'blind'),
  (8383, 30, 17, 'MV', 'Initiativen zur Regulierung suchtfördernder Mechanismen wie Lootboxen fortführen und unterstützen.', '{3004}', null, 1, 1, null, 'Lootboxen ähneln Glücksspiel, Wirkung von Regulierung ist kaum untersucht. Zuständig sind Bund und EU, das Land kann nur Initiativen unterstützen.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=64', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8384, 30, 17, 'MV', 'Eigenständige Förderrichtlinie für Sucht- und Drogenberatung mit ausreichenden, verlässlichen Landesmitteln wieder einführen.', '{3006}', 8321, 1, 3, null, 'Sichert vorhandene Angebote, schafft aber kaum zusätzlichen Zugang und senkt die Scham-Hürde nicht. Rechtlich und finanziell leicht umsetzbar.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=62', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8385, 30, 17, 'MV', 'Suchtprävention und Suchtberatung als Pflichtaufgabe der Gesundheitsämter verankern.', '{3006}', 8321, 1, 3, null, 'Sichert vorhandene Angebote, schafft aber kaum zusätzlichen Zugang und senkt die Scham-Hürde nicht. Rechtlich und finanziell leicht umsetzbar.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=62', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8386, 30, 17, 'MV', 'Niedrigschwellige, anonyme Beratungsangebote ausbauen.', '{3006}', 8319, 2, 3, null, 'Anonymität und kurze Wege senken die Hemmschwelle durch Scham; Wirkung auf die Inanspruchnahme ist kaum untersucht. Finanzierbar und kurzfristig umsetzbar.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=64', null, 'offen', '2026-10-06', false, true, 'blind'),
  (8589, 30, 18, null, 'Drug-Checking, Konsumräume und Substitutionsangebote stärker fördern.', '{3005}', null, 2, 2, null, 'Konsumräume senken Überdosierungen ohne mehr Konsum, Substitution ist gut belegt; Drug-Checking ändert Konsumabsichten, Gesundheitsfolgen sind weniger untersucht. Der Bund kann fördern, Betrieb und Konsumräume regeln die Länder.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=133', 'https://doi.org/10.1016/j.drugalcdep.2014.10.012', 'belegt', '2026-10-07', false, true, 'blind'),
  (8590, 30, 18, null, 'Besitz und Gebrauch aller psychoaktiven Substanzen sanktionsfrei entkriminalisieren.', '{3005}', null, 1, 2, null, 'Entkriminalisierung senkt Hürden zu Hilfe und erhöht den Konsum laut Studien meist nicht, ändert aber nichts an unbekannten Wirkstoffen am Schwarzmarkt; Erfahrungen (Portugal, Oregon) gemischt. Per Bundesgesetz möglich, Spannungen mit UN-Recht.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=154', 'https://doi.org/10.1136/bmjopen-2019-035148', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8591, 30, 18, null, 'Regulierten Verkauf einzelner noch illegaler Substanzen an Erwachsene in Modellprojekten erproben.', '{3005}', null, 1, 1, null, 'Regulierter Verkauf macht Wirkstoff und Dosis bekannt, Modellprojekte erreichen aber nur wenige; Wirkung kaum untersucht. Verkauf widerspricht UN-Konventionen und EU-Rahmenbeschluss, die Deutschland nicht allein ändert.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=155', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8592, 30, 18, null, 'Teillegalisierung von Cannabis beibehalten und durch Verkauf und Beratung in Fachgeschäften ausbauen.', '{3005}', 8329, 2, 1, null, 'Geprüfte Qualität kann Verunreinigungen senken; Studien zeigen gemischte Folgen für Konsum und Gesundheit. Hängt von EU- und UN-Recht ab, das Deutschland nicht allein ändert.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=155', 'https://europepmc.org/articles/PMC10176789', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8593, 30, 18, null, 'Aufklärung, Konsumkompetenz und Entstigmatisierung des Substanzgebrauchs sowie gemeindebasierte Prävention fördern.', '{3006}', null, 2, 3, null, 'Kontakt- und Aufklärungsangebote verringerten Stigma in fast allen untersuchten Studien; ob mehr Betroffene Hilfe suchen, ist kaum belegt, Umfang der Förderung offen. Bundesprogramme dafür bestehen.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=133', 'https://europepmc.org/articles/PMC3272222', 'belegt', '2026-10-07', false, true, 'blind'),
  (8594, 30, 18, null, 'Glücksspiel in der Suchtprävention verstärkt berücksichtigen.', '{3004}', null, 1, 3, null, 'Präventionsprogramme zu Glücksspiel zeigten in weniger als der Hälfte der Studien Verhaltenseffekte; Angebot und Werbung bleiben unverändert. Bundesweite Präventionsarbeit ist bereits etabliert und leicht ausbaubar.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=133', 'https://doi.org/10.1016/j.addbeh.2018.11.048', 'gemischt', '2026-10-07', false, true, 'blind'),
  (8598, 30, 18, 'BE', 'Diamorphin-Substitution ausbauen und drogenabhängigen Menschen Zugang zu psychotherapeutischer Hilfe ermöglichen', '{3006}', 8322, 2, 2, null, 'Konsumräume erreichen Randgruppen und senken Überdosierungen ohne mehr Konsum; Substitution ist gut belegt. Räume brauchen Landesrecht, Therapieplätze Personal.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=84', 'https://doi.org/10.1016/j.drugalcdep.2014.10.012', 'belegt', '2026-10-08', false, true, 'blind');

